package app.hiro.berrybfcache.patches;
import com.android.tools.smali.dexlib2.iface.reference.*;import com.android.tools.smali.dexlib2.immutable.reference.*;
import java.io.*;import java.util.*;import java.util.function.*;
import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.immutable.*;import com.android.tools.smali.dexlib2.immutable.instruction.*;
public final class NativeMetadataGuardTest {
 static Map<String,ClassDef>original=new LinkedHashMap<>();static BfCacheRepairPatch.Profile profile;
 static Method finish(Map<String,ClassDef>c){for(Method m:c.get("Lc70;").getMethods())if(m.getName().equals("onPageFinished"))return m;throw new AssertionError();}
 static void reject(Map<String,ClassDef>c,String name){try{NativeCompletionStructure.discover(c,profile,finish(c));throw new AssertionError("Accepted "+name);}catch(IllegalStateException ok){System.out.println("PASS rejected "+name);}}
 static Map<String,ClassDef>mutate(String type,String name,BiFunction<Integer,Instruction,Instruction>change){Map<String,ClassDef>c=new LinkedHashMap<>(original);ClassDef owner=c.get(type);List<Method>ms=new ArrayList<>();int changes=0;for(Method m:owner.getMethods()){if(!m.getName().equals(name)){ms.add(m);continue;}MethodImplementation impl=m.getImplementation();List<Instruction>is=new ArrayList<>();int j=0;for(Instruction i:impl.getInstructions()){Instruction n=change.apply(j++,i);if(n!=i)changes++;is.add(n);}ms.add(new ImmutableMethod(m.getDefiningClass(),m.getName(),m.getParameters(),m.getReturnType(),m.getAccessFlags(),m.getAnnotations(),m.getHiddenApiRestrictions(),new ImmutableMethodImplementation(impl.getRegisterCount(),is,impl.getTryBlocks(),impl.getDebugItems())));}if(changes!=1)throw new AssertionError("Expected one mutation, got "+changes);c.put(type,new ImmutableClassDef(owner.getType(),owner.getAccessFlags(),owner.getSuperclass(),owner.getInterfaces(),owner.getSourceFile(),owner.getAnnotations(),owner.getFields(),ms));return c;}
 public static void main(String[]a)throws Exception{
  MultiDexContainer<? extends DexFile>d=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(37));for(String n:d.getDexEntryNames())for(ClassDef c:d.getEntry(n).getDexFile().getClasses())original.put(c.getType(),c);
  profile=BfCacheStructure.discover(original,"Lc70;","Lc41;","Ltt5;","Lcx;");NativeCompletionStructure.discover(original,profile,finish(original));System.out.println("PASS positive original");
  reject(mutate("Lc70;","onPageFinished",(j,i)->refName(i,"getUrl")?new ImmutableInstruction35c(Opcode.INVOKE_INTERFACE,1,1,0,0,0,0,((ReferenceInstruction)i).getReference()):i),"URL getter receiver is not the owned adapter");
  reject(mutate("Lc70;","onPageFinished",(j,i)->refName(i,"getTitle")?new ImmutableInstruction35c(Opcode.INVOKE_INTERFACE,1,1,0,0,0,0,((ReferenceInstruction)i).getReference()):i),"title getter receiver is not the owned adapter");
  reject(mutate("Lc70;","onPageFinished",(j,i)->fieldRef(i,"Lns5;","n",Opcode.IPUT_OBJECT)?new ImmutableInstruction22c(Opcode.IPUT_OBJECT,((TwoRegisterInstruction)i).getRegisterA(),6,((ReferenceInstruction)i).getReference()):i),"URL metadata receiver is not owned metadata");
  reject(mutate("Lc70;","onPageFinished",(j,i)->fieldRef(i,"Ltt5;","l",Opcode.IGET_OBJECT)?new ImmutableInstruction22c(Opcode.IGET_OBJECT,((TwoRegisterInstruction)i).getRegisterA(),6,((ReferenceInstruction)i).getReference()):i),"metadata load receiver is not owned tab");
  reject(mutate("Lc70;","onPageFinished",(j,i)->fieldRef(i,"Lns5;","n",Opcode.IPUT_OBJECT)?new ImmutableInstruction22c(Opcode.IPUT_OBJECT,6,((TwoRegisterInstruction)i).getRegisterB(),((ReferenceInstruction)i).getReference()):i),"URL field value is not the getter result");
  reject(mutate("Lc70;","onPageFinished",(j,i)->fieldRef(i,"Lns5;","o",Opcode.IPUT_OBJECT)?new ImmutableInstruction22c(Opcode.IPUT_OBJECT,((TwoRegisterInstruction)i).getRegisterA(),((TwoRegisterInstruction)i).getRegisterB(),new ImmutableFieldReference("Lns5;","n","Ljava/lang/String;")):i),"URL and title writes target the same field");
  reject(privateField("Lns5;","n"),"URL field is not public");
  reject(privateField("Lns5;","o"),"title field is not public");
  reject(privateField("Ltt5;","l"),"metadata owner field is not public");
  NativeCompletionStructure n=NativeCompletionStructure.discover(original,profile,finish(original));
  if(!n.metadata.equals("Ltt5;->l:Lns5;")||!n.metadataUrl.equals("Lns5;->n:Ljava/lang/String;")||!n.metadataTitle.equals("Lns5;->o:Ljava/lang/String;"))throw new AssertionError("wrong positive metadata");
  String code=n.code(profile);if(!code.contains("if-eqz v0, :failed")||!code.contains("if-ne v2, p1, :failed")||!code.contains(":done\nconst/4 v0, 0x1\nreturn v0")||!code.endsWith(":failed\nconst/4 v0, 0x0\nreturn v0")||code.contains("return-void"))throw new AssertionError("wrong completion ABI");
  System.out.println("PASS boolean completion ownership guards");
 }
 static boolean refName(Instruction i,String n){return i instanceof ReferenceInstruction&&((ReferenceInstruction)i).getReference()instanceof MethodReference&&((MethodReference)((ReferenceInstruction)i).getReference()).getName().equals(n);}
 static boolean fieldRef(Instruction i,String owner,String name,Opcode opcode){if(i.getOpcode()!=opcode||!(i instanceof ReferenceInstruction)||!(((ReferenceInstruction)i).getReference()instanceof FieldReference))return false;FieldReference f=(FieldReference)((ReferenceInstruction)i).getReference();return f.getDefiningClass().equals(owner)&&f.getName().equals(name);}
 static Map<String,ClassDef>privateField(String type,String name){Map<String,ClassDef>c=new LinkedHashMap<>(original);ClassDef owner=c.get(type);List<Field>fs=new ArrayList<>();int changes=0;for(Field f:owner.getFields()){if(!f.getName().equals(name)){fs.add(f);continue;}changes++;fs.add(new ImmutableField(f.getDefiningClass(),f.getName(),f.getType(),(f.getAccessFlags()&~1)|2,f.getInitialValue(),f.getAnnotations(),f.getHiddenApiRestrictions()));}if(changes!=1)throw new AssertionError();c.put(type,new ImmutableClassDef(owner.getType(),owner.getAccessFlags(),owner.getSuperclass(),owner.getInterfaces(),owner.getSourceFile(),owner.getAnnotations(),fs,owner.getMethods()));return c;}
}
